from operator import add, floordiv, mul, sub

token_count = int(input())
tokens = input().split()
operators = {"+": add, "-": sub, "*": mul, "/": floordiv}
stack = []
for token in tokens:
    if token not in operators:
        stack.append(int(token))
        continue
    if len(stack) < 2:
        print("ERROR UNDERFLOW")
        break
    right = stack.pop()
    left = stack.pop()
    if token == "/" and right == 0:
        print("ERROR ZERO DIVISOR")
        break
    stack.append(operators[token](left, right))
else:
    if len(stack) == 1:
        print(stack[0])
    else:
        print("ERROR EXTRA OPERANDS")
